package app.kivo.store;
/** Public DownloadManager reason codes; no Android dependency for deterministic tests. */
final class DownloadReason {
 static String waiting(int reason){switch(reason){case 1:return "Android espera para reintentar. La descarga se reanudará automáticamente si el servidor lo permite.";case 2:return "Sin conexión. Android continuará cuando vuelva la red.";case 3:return "Esperando una red Wi-Fi. Revisa la conexión y la opción Solo Wi-Fi.";default:return "Android ha puesto la descarga en espera. Continuará cuando la red y el servidor lo permitan.";}}
 static String failed(int reason){if(reason==404||reason==410)return "El archivo ya no está en el servidor. Actualiza el catálogo y abre la ficha antes de reintentar.";if(reason==401||reason==403)return "El servidor rechazó el acceso al archivo. Comprueba el origen desde la ficha; repetir la descarga puede no resolverlo.";if(reason>=500&&reason<=599)return "El servidor no pudo entregar el archivo. Reintenta más tarde.";switch(reason){case 1006:return "No hay espacio suficiente. Libera almacenamiento antes de reintentar.";case 1007:return "El almacenamiento de destino no está disponible.";case 1008:return "El servidor no permitió reanudar. Reintentar iniciará una descarga nueva.";case 1001:case 1009:return "Android no pudo guardar el archivo. Revisa el almacenamiento y reintenta.";case 1002:case 1004:case 1005:return "La conexión o respuesta del servidor falló. Reintenta cuando tengas una conexión estable.";default:return "No se pudo completar la descarga. Reintentar inicia una nueva solicitud; la reanudación depende del servidor.";}}
}
